from fractions import Fraction as F
def finish(rates_by_day, total=F(1), limit=10000):
    """rates_by_day(d) -> work rate in period d (0-based); returns exact finishing time."""
    done, t, d = F(0), F(0), 0
    while d < limit:
        r = rates_by_day(d)
        if r > 0 and done + r >= total:
            return t + (total - done) / r
        done += r; t += 1; d += 1

hits = []
for c in range(1, 2000):
    rc = F(1, c); rb = 2 * rc; ra = 3 * rb
    if finish(lambda d: ra + rb + rc) == 18: hits.append(1 / ra)
assert len(hits) == 1
